evt = on("NormativeCompilationCompleted")
deliverable = sys.acquire("NormativeDeliverable", {"id": evt["normativeDeliverableId"]})
findings = []
if deliverable["coherenceFindings"] != []:
    sys.emit("NormativeCoherenceViolation", {
        "normativeDeliverableId": evt["normativeDeliverableId"],
        "findings": deliverable["coherenceFindings"]
    })
else:
    result = sys.modify("NormativeDeliverable", {"id": evt["normativeDeliverableId"]}, {"validationStatus": "validated"})
    sys.emit("NormativeDeliverablePublished", {
        "normativeDeliverableId": evt["normativeDeliverableId"],
        "targetSystemArchetype": deliverable["targetSystemArchetype"],
        "version": deliverable["version"],
        "publishedAt": now()
    })

evt = on("DataSubjectErasureRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    records = sys.acquire("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
    has_exemption = records["hasLegalRetentionObligation"] or records["requiredForLegalClaim"]
    if has_exemption:
        sys.emit("ErasureRefused", {"requestId": evt["requestId"], "reason": "legal-exemption", "exemptionBasis": records["exemptionBasis"]})
    else:
        result = sys.delete("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
        sys.emit("ErasureCompleted", {"requestId": evt["requestId"], "dataSubjectId": evt["dataSubjectId"], "erasedAt": now()})

evt = on("DataSubjectPortabilityRequest")
subject = sys.acquire("DataSubject", {"id": evt["dataSubjectId"]})
if subject == None:
    sys.emit("RequestDenied", {"requestId": evt["requestId"], "reason": "identity-not-verified"})
else:
    records = sys.acquire("PersonalData", {"dataSubjectId": evt["dataSubjectId"]})
    export = sys.create("DataExport", {"dataSubjectId": evt["dataSubjectId"], "format": "structured", "content": records, "exportedAt": now()})
    if evt["directTransfer"] and evt["targetController"]:
        sys.emit("DirectTransferInitiated", {"requestId": evt["requestId"], "targetController": evt["targetController"], "exportId": export["id"]})
    else:
        sys.emit("PortabilityExportReady", {"requestId": evt["requestId"], "exportId": export["id"]})
